// The song tables read by music.c. source/songs.c is GENERATED by tools/music/build_songs.py from the analysis of
// the source songs (tools/music/analysis/*.json) and the hand-tuned definitions in tools/music/songs_src.py;
// run `make songs` after editing either. Nothing in the sequencer is tied to one tune: a Song is the whole tune.
#ifndef WORDPASS_SONGS_H
#define WORDPASS_SONGS_H

#include "game.h"

// One voice's instrument: duty (percent) for the first atkFrames frames, then dutySus; level at the onset, the level
// it settles to and the fall per frame; vibrato after vibDelay frames at +/- baseHz / vibDiv (0 = none); release.
typedef struct {
    u8 dutyAtk, dutySus, atkFrames;
    u8 volOn, volSus, decay;
    u8 vibDelay, vibDiv;
    u8 release;
} Inst;

// Scales (index into SCALES in music.c)
enum { MODE_MAJOR = 0, MODE_MINOR, MODE_DORIAN, MODE_MIXOLYDIAN, MODE_PHRYGIAN, MODE_LYDIAN, MODE_HARMINOR, MODE_HIJAZ, MODE_COUNT };
// Where a song plays: the menu screens, the Classic rotation, the Daily Pass, Lockdown and FIRE FAST
enum { SR_MENU = 0, SR_CLASSIC, SR_DAILY, SR_DARK };

#define BASS_REST (-128)

// The drums at one level. Bit n of a mask is step n of the bar; the pattern has four bars.
typedef struct {
    u16 kick[4], snare[4], ghost[4], open[4];   // kick, snare, a soft kick, an open hat
    u8  hat[16];                                // closed hat level per step of the bar (0 = none)
    u8  fill;                                   // 1: the last four steps of the pattern are a rising snare roll
} DrumLevel;

typedef struct {
    const char *name;
    u8  role, root, mode, harm;       // SR_*; MIDI tonic; MODE_*; 1 = the V chord raises the 7th (harmonic minor pull)
    u8  stepFrames, leadOct, gain, tap;   // frames per 16th step (5..12); octave of the lead over the root; level of the music voices (percent); 1 = minor pentatonic taps
    u8  attVol, attDuty, attPad;      // the menu mix (the title): hook level, hook duty (percent) and pad level
    u8  kickVol, snareVol, ghostVol, openVol;
    u16 kickHz, snareHz, hatHz, openHz;
    u8  padMax, padDeg[2];            // the pad's full level and the two chord degrees it alternates between
    u8  arp[4];                       // the pulse arpeggio: chord degree offsets per beat
    u8  chordA[4], chordB[4];         // chord root degree per bar in sections A and B
    s8  bass[2][16];                  // semitones over the chord root per step (BASS_REST = none); the second is bar 4
    u16 bassAccent;                   // steps played at full level (the others at 78%)
    u8  hookA[64], hookB[64];         // scale degrees 1..14, 0 = hold, 99 = rest
    DrumLevel drum[3];                // levels 1..3
    Inst inst[4];                     // hook, pulse, bass, pad
} Song;

extern const Song SONGS[];
extern const int NSONGS;
void musicForceSong(const Song *song);   // tests: play this song whatever the rules say (NULL: the rules again)
int  musicSongIndex(void);               // index of the current song in SONGS (-1 when forced)
enum { SONG_VOICES = 4 };            // instruments a song sets (the first four voices of music.c)

#endif
